const leads = $('Get Leads Requiring Follow-up').all();
const configs = $('Get Active Businesses').all();
const now = Date.now();
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const candidates = [];
for (const l of leads) {
  const j = l.json;
  const bid = String(j.business_id || '').trim();
  const cfgRow = configs.find(
    (c) => String(c.json.business_id || '').trim() === bid
  );
  if (!cfgRow) continue;
  const cj = cfgRow.json;

  // Business must be active.
  if (String(cj.active || '').trim().toLowerCase() !== 'true') continue;

  // Status must not be terminal.
  const status = String(j.status || '').trim().toLowerCase();
  if (['booked', 'lost', 'closed', 'no_response'].indexOf(status) !== -1) continue;

  // followup_count < max_followups.
  const count = Number(j.followup_count || 0) || 0;
  const max = Number(cj.max_followups || 3) || 3;
  if (!(count < max)) continue;

  // next_followup_at must exist and be <= now.
  const rawNext = String(j.next_followup_at || '').trim();
  if (!rawNext) continue;
  const nextTs = new Date(rawNext).getTime();
  if (!isFinite(nextTs) || nextTs > now) continue;

  // Valid email required.
  const email = String(j.email || '').trim();
  if (!EMAIL_RE.test(email)) continue;

  candidates.push({
    json: Object.assign({}, j, {
      email: email,
      business_name: cj.business_name || '',
      owner_name: cj.owner_name || '',
      from_email: cj.from_email || '',
      reply_to_email: cj.reply_to_email || '',
      followup_delay_hours: Number(cj.followup_delay_hours || 24) || 24,
      max_followups: max,
      _esc_name: esc(j.name),
      _esc_business_name: esc(cj.business_name || ''),
      _esc_service: esc(j.service),
      _esc_booking_link: esc(j.booking_link),
      _noCandidates: false
    })
  });
}

if (candidates.length === 0) {
  return [{ json: { _noCandidates: true } }];
}
return candidates;

