return $input.all().map((it) => {
  const j = it.json;
  const count = (Number(j.followup_count || 0) || 0) + 1;
  const max = Number(j.max_followups || 3) || 3;
  const delay = Number(j.followup_delay_hours || 24) || 24;
  const nowIso = new Date().toISOString();
  const reachedMax = count >= max;
  return {
    json: Object.assign({}, j, {
      followup_count: count,
      last_contact_at: nowIso,
      next_followup_at: reachedMax ? '' : new Date(Date.now() + delay * 3600 * 1000).toISOString(),
      status: reachedMax ? 'no_response' : String(j.status || 'new'),
      updated_at: nowIso
    })
  };
});
